/// Raven `FighterDamageRoutine`.
///
/// Source: `oracle/oracle/codemp/game/FighterNPC.c:935-1089`
pub fn FighterDamageRoutine(
    pVeh: *mut Vehicle_t,
    parent: *mut bgEntity_t,
    parentPS: *mut playerState_t,
    riderPS: *mut playerState_t,
    isDead: qboolean,
) {
    unsafe {
        if (*pVeh).m_iRemovedSurfaces == 0 {
            // Still in one piece
            if !(*pVeh).m_pParentEntity.is_null() && isDead != qfalse {
                // Death spiral
                (*pVeh).m_ucmd.upmove = 0;

                let parent_ent = (*pVeh).m_pParentEntity.cast::<gentity_t>();
                let num = (*parent_ent).s.number;

                if num % 3 != 0 {
                    // NOT everyone should do this
                    (*pVeh).m_vOrientation[0] += (*pVeh).m_fTimeModifier;
                    if BG_UnrestrainedPitchRoll(riderPS, pVeh) == qfalse {
                        if (*pVeh).m_vOrientation[0] > 60.0f32 {
                            (*pVeh).m_vOrientation[0] = 60.0f32;
                        }
                    }
                } else if num % 2 == 0 {
                    (*pVeh).m_vOrientation[0] -= (*pVeh).m_fTimeModifier;
                    if BG_UnrestrainedPitchRoll(riderPS, pVeh) == qfalse {
                        if (*pVeh).m_vOrientation[0] < -60.0f32 {
                            (*pVeh).m_vOrientation[0] = -60.0f32;
                        }
                    }
                }

                if num % 2 != 0 {
                    (*pVeh).m_vOrientation[1] += (*pVeh).m_fTimeModifier;
                    (*pVeh).m_vOrientation[2] += (*pVeh).m_fTimeModifier * 4.0f32;
                } else {
                    (*pVeh).m_vOrientation[1] -= (*pVeh).m_fTimeModifier;
                    (*pVeh).m_vOrientation[2] -= (*pVeh).m_fTimeModifier * 4.0f32;
                }
            }
            return;
        }

        // We have at least one broken piece
        (*pVeh).m_ucmd.upmove = 0;

        // If off the ground and not suspended, pitch down
        if (*pVeh).m_LandTrace.fraction >= 0.1f32 {
            if FighterSuspended(pVeh, parentPS) == qfalse {
                let parent_ent = (*pVeh).m_pParentEntity.cast::<gentity_t>();
                let num = (*parent_ent).s.number;

                if num % 3 != 0 {
                    (*pVeh).m_vOrientation[0] += (*pVeh).m_fTimeModifier;
                    if BG_UnrestrainedPitchRoll(riderPS, pVeh) == qfalse {
                        if (*pVeh).m_vOrientation[0] > 60.0f32 {
                            (*pVeh).m_vOrientation[0] = 60.0f32;
                        }
                    }
                } else if num % 4 == 0 {
                    (*pVeh).m_vOrientation[0] -= (*pVeh).m_fTimeModifier;
                    if BG_UnrestrainedPitchRoll(riderPS, pVeh) == qfalse {
                        if (*pVeh).m_vOrientation[0] < -60.0f32 {
                            (*pVeh).m_vOrientation[0] = -60.0f32;
                        }
                    }
                }
            }
        }

        // Wing damage effects
        let c = 0x01;  // SHIPSURF_BROKEN_C
        let d = 0x02;  // SHIPSURF_BROKEN_D
        let e = 0x04;  // SHIPSURF_BROKEN_E
        let f = 0x08;  // SHIPSURF_BROKEN_F

        if (((*pVeh).m_iRemovedSurfaces & c) != 0 || ((*pVeh).m_iRemovedSurfaces & d) != 0)
            && (((*pVeh).m_iRemovedSurfaces & e) != 0 || ((*pVeh).m_iRemovedSurfaces & f) != 0)
        {
            // Wings on both sides broken
            let mut factor = 2.0f32;
            if ((*pVeh).m_iRemovedSurfaces & e) != 0
                && ((*pVeh).m_iRemovedSurfaces & f) != 0
                && ((*pVeh).m_iRemovedSurfaces & c) != 0
                && ((*pVeh).m_iRemovedSurfaces & d) != 0
            {
                factor *= 2.0f32;  // All wings broken
            }

            let parent_ent = (*pVeh).m_pParentEntity.cast::<gentity_t>();
            let num = (*parent_ent).s.number;
            if num % 2 == 0 || num % 6 == 0 {
                factor *= 4.0f32;
            }

            (*pVeh).m_vOrientation[2] += (*pVeh).m_fTimeModifier * factor;
        } else if ((*pVeh).m_iRemovedSurfaces & c) != 0
            || ((*pVeh).m_iRemovedSurfaces & d) != 0
        {
            // Left wing broken
            let mut factor = 2.0f32;
            if ((*pVeh).m_iRemovedSurfaces & c) != 0 && ((*pVeh).m_iRemovedSurfaces & d) != 0 {
                factor *= 2.0f32;
            }

            let parent_ent = (*pVeh).m_pParentEntity.cast::<gentity_t>();
            let num = (*parent_ent).s.number;
            if num % 2 == 0 || num % 6 == 0 {
                factor *= 4.0f32;
            }

            (*pVeh).m_vOrientation[2] += factor * (*pVeh).m_fTimeModifier;
        } else if ((*pVeh).m_iRemovedSurfaces & e) != 0
            || ((*pVeh).m_iRemovedSurfaces & f) != 0
        {
            // Right wing broken
            let mut factor = 2.0f32;
            if ((*pVeh).m_iRemovedSurfaces & e) != 0 && ((*pVeh).m_iRemovedSurfaces & f) != 0 {
                factor *= 2.0f32;
            }

            let parent_ent = (*pVeh).m_pParentEntity.cast::<gentity_t>();
            let num = (*parent_ent).s.number;
            if num % 2 == 0 || num % 6 == 0 {
                factor *= 4.0f32;
            }

            (*pVeh).m_vOrientation[2] -= factor * (*pVeh).m_fTimeModifier;
        }
    }
}

/// Raven `FighterYawAdjust`.
///
/// Source: `oracle/oracle/codemp/game/FighterNPC.c:1299-1323`
pub fn FighterYawAdjust(
    pVeh: *mut Vehicle_t,
    riderPS: *mut playerState_t,
    parentPS: *mut playerState_t,
) {
    unsafe {
        let angDif = AngleSubtract(
            (*pVeh).m_vOrientation[1],
            (*riderPS).viewangles[1],
        );

        if !parentPS.is_null() && (*parentPS).speed != 0.0f32 {
            let mut s = (*parentPS).speed;
            let maxDif = (*pVeh).m_pVehicleInfo.as_ref().map(|vi| vi.turningSpeed).unwrap_or(1.0) * 0.8f32;

            if s < 0.0f32 {
                s = -s;
            }
            let mut scaled = angDif * s / (*pVeh).m_pVehicleInfo.as_ref().map(|vi| vi.speedMax).unwrap_or(1.0);
            if scaled > maxDif {
                scaled = maxDif;
            } else if scaled < -maxDif {
                scaled = -maxDif;
            }
            (*pVeh).m_vOrientation[1] =
                AngleNormalize180((*pVeh).m_vOrientation[1] - scaled * ((*pVeh).m_fTimeModifier * 0.2f32));
        }
    }
}

